fn solve(coins: Vec<i8>) -> i8 {
    // Sum into a wider integer to avoid overflow (max sum is 5 * 100 = 500).
    let sum: i32 = coins.iter().map(|&x| x as i32).sum();

    // Check strictly positive and divisible by 5.
    if sum > 0 && sum % 5 == 0 {
        // The average will be between 0 and 100, fits in i8.
        (sum / 5) as i8
    } else {
        -1
    }
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_valid_average() {
        assert_eq!(solve(vec![10, 20, 30, 40, 50]), 30);
        assert_eq!(solve(vec![0, 0, 0, 0, 5]), 1);
        assert_eq!(solve(vec![100, 100, 100, 100, 100]), 100);
    }

    #[test]
    fn test_invalid() {
        // Sum is zero
        assert_eq!(solve(vec![0, 0, 0, 0, 0]), -1);
        // Sum is positive but not divisible by 5
        assert_eq!(solve(vec![1, 2, 3, 4, 5]), -1); // sum = 15, actually divisible -> 3 (oops!)
        // Correction: 1+2+3+4+5 = 15, divisible by 5, average = 3
        assert_eq!(solve(vec![1, 2, 3, 4, 6]), -1); // sum = 16, not divisible by 5
    }
}